/* ВЫБОР ДАТЫ. Календарь в клетку: поле «дата» вместо ручного набора, быстрые
   кнопки («сегодня», «начало месяца», «конец месяца»), ряд дат с шагом и счёт
   рабочих дней. Даты строятся обычным JS Date, а в число таблицы переводит
   «дата(строка)» — так плагин не зависит от того, с какого дня начинается
   отсчёт в книге. */

const МЕСЯЦЫ = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня',
                'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];
const ДНИ = ['воскресенье', 'понедельник', 'вторник', 'среда', 'четверг', 'пятница', 'суббота'];

const дваЗнака = ч => (ч < 10 ? '0' : '') + ч;
const кСтроке = д => дваЗнака(д.getDate()) + '.' + дваЗнака(д.getMonth() + 1) + '.' + д.getFullYear();
const изПоля = с => {
  const м = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(с || ''));      // поле «дата» отдаёт ГГГГ-ММ-ДД
  if(м) return new Date(+м[1], +м[2] - 1, +м[3]);
  const р = /^(\d{1,2})\.(\d{1,2})\.(\d{4})$/.exec(String(с || ''));
  if(р) return new Date(+р[3], +р[2] - 1, +р[1]);
  return new Date();
};
const рабочий = д => д.getDay() !== 0 && д.getDay() !== 6;

const ФОРМАТЫ = {
  'ДД.ММ.ГГГГ': 'dd.mm.yyyy',
  'Д мес ГГГГ': 'd mmm yy',
  'ГГГГ-ММ-ДД': 'yyyy-mm-dd',
  'ДД.ММ.ГГГГ ЧЧ:ММ': 'dd.mm.yyyy h:mm',
  'без формата': null,
};

function поставить(д){
  const п = параметры({}), в = книга.выделение;
  const к = ячейка(в.адрес);
  к.значение = дата(кСтроке(д));
  const ф = ФОРМАТЫ[п.формат];
  if(ф) к.формат = ф;
  панель.поле('дата', д.getFullYear() + '-' + дваЗнака(д.getMonth() + 1) + '-' + дваЗнака(д.getDate()));
  панель.сообщение(в.адрес + ' ← ' + кСтроке(д) + ', ' + ДНИ[д.getDay()]);
  Показать();
}

function Вставить(){ поставить(изПоля(параметры({}).дата)); }
function Сегодня(){ поставить(new Date()); }
function НачалоМесяца(){ const д = изПоля(параметры({}).дата); поставить(new Date(д.getFullYear(), д.getMonth(), 1)); }
function КонецМесяца(){ const д = изПоля(параметры({}).дата); поставить(new Date(д.getFullYear(), д.getMonth() + 1, 0)); }

/* Ряд дат вниз по столбцу: день, рабочий день, неделя, месяц, год */
function Ряд(){
  const п = параметры({}), в = книга.выделение;
  const сколько = Math.max(1, Math.min(100000, +п.сколько || 12));
  const шаг = п.шаг || 'день';
  let д = изПоля(п.дата);
  const строки = [];
  for(let i = 0; i < сколько; i++){
    строки.push([дата(кСтроке(д))]);
    if(шаг === 'день') д = new Date(д.getFullYear(), д.getMonth(), д.getDate() + 1);
    else if(шаг === 'рабочий день'){ do { д = new Date(д.getFullYear(), д.getMonth(), д.getDate() + 1); } while(!рабочий(д)); }
    else if(шаг === 'неделя') д = new Date(д.getFullYear(), д.getMonth(), д.getDate() + 7);
    else if(шаг === 'месяц') д = new Date(д.getFullYear(), д.getMonth() + 1, д.getDate());
    else д = new Date(д.getFullYear() + 1, д.getMonth(), д.getDate());
  }
  const л = лист(в.лист), область = в.адрес + ':' + столбецИмя(в.столбец) + (в.строка + сколько - 1);
  л.диапазон(область).записать(строки);
  const ф = ФОРМАТЫ[п.формат];
  if(ф) л.диапазон(область).формат = ф;
  л.диапазон(область).выделить();
  панель.сообщение('Записано дат: ' + сколько + ' (' + шаг + ') в ' + область);
}

function столбецИмя(с){ let имя = ''; while(с > 0){ const о = (с - 1) % 26; имя = String.fromCharCode(65 + о) + имя; с = (с - о - 1) / 26; } return имя; }

/* Что в клетке под курсором — и сколько до неё дней */
function Показать(){
  const в = книга.выделение;
  if(!в) return;
  const з = ячейка(в.адрес).значение;
  const п = параметры({});
  const выбрана = изПоля(п.дата);
  const ряды = [['Клетка', в.адрес]];
  if(typeof з === 'number' && з > 0 && з < 2958466){
    /* серийное число книги → дата: через ту же «дата()», но обратным подбором по году */
    const д = изСерийного(з);
    ряды.push(['В клетке', кСтроке(д) + ', ' + ДНИ[д.getDay()]],
              ['Словами', д.getDate() + ' ' + МЕСЯЦЫ[д.getMonth()] + ' ' + д.getFullYear()]);
    const дней = Math.round((д - выбрана) / 86400000);
    ряды.push(['От выбранной', дней === 0 ? 'тот же день' : (дней > 0 ? '+' : '') + дней + ' дн.']);
    ряды.push(['Рабочих между', String(рабочихМежду(выбрана, д))]);
  } else ряды.push(['В клетке', з === null || з === undefined || з === '' ? 'пусто' : 'не дата']);
  ряды.push(['Выбрана', кСтроке(выбрана) + ', ' + ДНИ[выбрана.getDay()]]);
  панель.список('сведения', ряды);
}

/* серийное число книги → Date: 1 = 1 января 1900 года, как в таблицах */
function изСерийного(н){
  const дней = Math.floor(н) - (Math.floor(н) > 59 ? 2 : 1);   // поправка на несуществующее 29.02.1900
  return new Date(Date.UTC(1900, 0, 1 + дней));
}

function рабочихМежду(a, b){
  let от = a < b ? new Date(a) : new Date(b), до = a < b ? b : a, счёт = 0;
  от = new Date(от.getFullYear(), от.getMonth(), от.getDate() + 1);
  while(от <= до){ if(рабочий(от)) счёт++; от = new Date(от.getFullYear(), от.getMonth(), от.getDate() + 1); }
  return (a < b ? 1 : -1) * счёт;
}

function Старт(){
  const д = new Date();
  панель.поле('дата', д.getFullYear() + '-' + дваЗнака(д.getMonth() + 1) + '-' + дваЗнака(д.getDate()));
  Показать();
}

/* Пункт меню на любой клетке */
function ИзМеню(){ поставить(изПоля(параметры({}).дата)); }
